import java.util.*;
import java.io.*;
import java.math.BigInteger;

public class Main {
    static void solve(InputReader reader, OutputWriter writer)
            throws IOException {
        // Scanner scan = new Scanner(System.in);
        String a = reader.readLine();
        char c = a.charAt(0);
        String s = reader.readLine();
        char[] cc = { 'q', 'w', 'e', 'r', 't', 'y', 'u', 'i', 'o', 'p', 'a',
                's', 'd', 'f', 'g', 'h', 'j', 'k', 'l', ';', 'z', 'x', 'c',
                'v', 'b', 'n', 'm', ',', '.', '/' };
        if(c == 'R'){
            for (int i = 0; i < s.length(); ++i){
                int index = 0;
                for (int k = 0; k < cc.length; ++k){
                    if(s.charAt(i) == cc[k]){
                        index = --k;
                    //  writer.println(index);
                        break;
                    }
                }
                if(i < s.length() - 1)
                    writer.print(cc[index]);
                else
                    writer.println(cc[index]);
            }
        }else{
            for (int i = 0; i < s.length(); ++i){
                int index = 0;
                for (int k = 0; k < cc.length; ++k){
                    if(s.charAt(i) == cc[k]){
                        index = ++k;
                        break;
                    }
                }
                if(i < s.length() - 1)
                    writer.print(cc[index]);
                else
                    writer.println(cc[index]);
            }
        }

    }

    public static void main(String[] args) throws Exception {
        InputReader reader = new InputReader(System.in);
        OutputWriter writer = new OutputWriter(System.out);
        try {
            solve(reader, writer);
        } catch (Exception e) {
            e.printStackTrace(System.out);
        } finally {
            writer.close();
        }
    }

}

class InputReader extends BufferedReader {
    public InputReader(InputStream in) {
        super(new InputStreamReader(in));
    }
}

class OutputWriter extends PrintWriter {
    public OutputWriter(PrintStream out) {
        super(new BufferedWriter(new OutputStreamWriter(out)));
    }
}
